const data = $input.first().json;

// Try JSON path first (n8n parses XML to JSON automatically)
try {
  const stacks = data?.DescribeStacksResponse?.DescribeStacksResult?.Stacks?.member;
  const stackArr = Array.isArray(stacks) ? stacks : [stacks];
  for (const stack of stackArr) {
    const outputs = stack?.Outputs?.member;
    const outputArr = Array.isArray(outputs) ? outputs : (outputs ? [outputs] : []);
    for (const o of outputArr) {
      if (o?.OutputKey === 'BackofficeApiUrl') {
        return [{ json: { backofficeApiUrl: o.OutputValue, message: '✅ Copy this URL and send it to Claude Code' } }];
      }
    }
  }
} catch(e) {}

// Fallback: regex on stringified response
const xmlStr = JSON.stringify(data);
const match = xmlStr.match(/BackofficeApiUrl.*?OutputValue.*?([^\\"]+api[^\\"]+)/);
if (match) {
  return [{ json: { backofficeApiUrl: match[1], message: '✅ Copy this URL and send it to Claude Code' } }];
}

return [{ json: { error: 'BackofficeApiUrl not found', rawKeys: Object.keys(data), rawResponse: JSON.stringify(data).substring(0, 1000) } }];
